const assert = require('node:assert/strict');
const fs = require('node:fs');
const http = require('node:http');
const vm = require('node:vm');
let handler;
let now = Date.parse('2026-08-31T23:59:59.999Z');
class Clock extends Date { static now() { return now; } }
vm.runInNewContext(fs.readFileSync('src/server.js', 'utf8'), {
  require(name) {
    assert.equal(name, 'http');
    return { createServer(fn) { handler = fn; return { listen() {} }; } };
  },
  URL, Date: Clock
}, { filename: 'src/server.js' });
const server = http.createServer(handler);
function request(method, path, body) {
  return new Promise((resolve, reject) => {
    const req = http.request({ host: '127.0.0.1', port: server.address().port, method, path }, res => {
      let text = '';
      res.on('data', c => text += c);
      res.on('end', () => resolve({ status: res.statusCode, text }));
    });
    req.on('error', reject);
    req.end(body ? JSON.stringify(body) : undefined);
  });
}
server.listen(0, '127.0.0.1', async () => {
  try {
    assert.deepEqual(JSON.parse((await request('GET', '/entries')).text), []);
    assert.equal((await request('POST', '/entries', { amount: 10, note: 'aug' })).status, 200);
    now = Date.parse('2026-09-01T00:00:00.000Z');
    await request('POST', '/entries', { amount: 20, note: 'sep' });
    const all = JSON.parse((await request('GET', '/entries')).text);
    assert.deepEqual(all.map(e => e.note), ['aug', 'sep']);
    for (const [month, expected] of [['2026-08', ['aug']], ['2026-09', ['sep']], ['2026-10', []]]) {
      const result = await request('GET', '/entries?month=' + month);
      assert.equal(result.status, 200);
      assert.deepEqual(JSON.parse(result.text).map(e => e.note), expected);
    }
    assert.equal(JSON.parse((await request('GET', '/entries')).text).length, 2);
    console.log('PASS: syntax; empty list; unfiltered list; August/September UTC boundary filtering; unmatched month; filtering preserves entries');
  } catch (error) {
    console.error(error);
    process.exitCode = 1;
  } finally {
    server.close();
  }
});
